INSERT INTO `entrepreneurs` VALUES ('1',1,'Alex Morgan','Founder & CEO','Alex Morgan is a visionary entrepreneur building innovative companies that create a more sustainable, connected and inclusive future.','www.alexmorgan.com','https://f005.backblazeb2.com/file/timeschicago/entrepreneurs/entrepreneur_1_0_1791722256651.jpg','38','United States','CleanTech & Aerospace','Technology','Male','$850 M','[{\"id\":\"c1\",\"name\":\"Tesla\",\"role\":\"CEO\",\"website\":\"www.tesla.com\",\"logoUrl\":\"https://upload.wikimedia.org/wikipedia/commons/e/e8/Tesla_logo.png\"}]','{\"id\":\"1\",\"rank\":1,\"name\":\"Alex Morgan\",\"titleRole\":\"Founder & CEO\",\"bio\":\"Alex Morgan is a visionary entrepreneur building innovative companies that create a more sustainable, connected and inclusive future.\",\"website\":\"www.alexmorgan.com\",\"photoUrl\":\"https://f005.backblazeb2.com/file/timeschicago/entrepreneurs/entrepreneur_1_0_1791722256651.jpg\",\"age\":38,\"country\":\"United States\",\"source\":\"CleanTech & Aerospace\",\"industry\":\"Technology\",\"gender\":\"Male\",\"netWorthMillions\":\"$850 M\",\"highlightText\":\"\",\"companies\":[{\"id\":\"c1\",\"name\":\"Tesla\",\"role\":\"CEO\",\"website\":\"www.tesla.com\",\"logoUrl\":\"https://upload.wikimedia.org/wikipedia/commons/e/e8/Tesla_logo.png\"}],\"editorLastUpdated\":\"Last Updated Oct 10, 2026, 9:00am\",\"editorBulletPoints\":[\"Alex Morgan oversees a portfolio of advanced frontier technology startups spanning 4 continents.\",\"His primary venture secured $140M in Series C financing at a valuation surpassing $1.2 billion.\",\"Morgan advocates for open-source AI infrastructure and decarbonized manufacturing systems.\",\"Recognized by Times Chicago as one of the top innovators reshaping international capital markets.\"],\"selfMadeScore\":\"\",\"philanthropyScore\":\"\",\"residence\":\"\",\"citizenship\":\"United States\",\"maritalStatus\":\"Single\",\"children\":\"\",\"education\":\"B.S in Electrical Engineering & Computer Science, Stanford University\",\"didYouKnowFacts\":[\"Founded his first commercial software enterprise at age 19 from a university dormitory.\",\"Holds 18 registered international patents in high-density energy storage and power management.\"],\"inTheirOwnWordsQuote\":\"\",\"inTheirOwnWordsQuote2\":\"\",\"inTheirOwnWordsQuotes\":[]}','2026-10-20 12:31:33',NULL,'',NULL,NULL,'','','','','','',NULL,NULL),('ent_1791812873499',2,'Larry Page','Founder & CEO','Larry Page stepped down as CEO of Alphabet, the parent company of Google, in 2019 but remains a board member and a controlling shareholder.','www.larrypage.com','https://f005.backblazeb2.com/file/timeschicago/entrepreneurs/entrepreneur_ent_1791812873499_1.webp','35','United States','CleanTech & Software','Technology','Male','$650 M','[]','{\"id\":\"ent_1791812873499\",\"rank\":2,\"name\":\"Larry Page\",\"titleRole\":\"Founder & CEO\",\"bio\":\"Larry Page stepped down as CEO of Alphabet, the parent company of Google, in 2019 but remains a board member and a controlling shareholder.\",\"website\":\"www.larrypage.com\",\"photoUrl\":\"https://f005.backblazeb2.com/file/timeschicago/entrepreneurs/entrepreneur_ent_1791812873499_1.webp\",\"age\":\"35\",\"country\":\"United States\",\"source\":\"CleanTech & Software\",\"industry\":\"Technology\",\"gender\":\"Male\",\"netWorthMillions\":\"$650 M\",\"companies\":[],\"highlightText\":\"\",\"editorLastUpdated\":\"Last Updated Oct 10, 2026, 9:00am\",\"editorBulletPoints\":[\"Larry Page leads transformative ventures shaping international markets.\"],\"inTheirOwnWordsQuote\":\"\",\"selfMadeScore\":8,\"philanthropyScore\":2,\"maritalStatus\":\"Single\",\"children\":0,\"residence\":\"\",\"citizenship\":\"United States\",\"education\":\"\",\"didYouKnowFacts\":[]}','2026-10-20 12:31:33',NULL,'',NULL,NULL,'','','','','','',NULL,NULL);
